/* generated by scripts/build-i18n.py from i18n/strings.json — edit the JSON, not this file */
(function () {
  var D = {"Diamond Hands":{"zh":"钻石手","ko":"다이아몬드 핸즈"},"Holds on long-horizon conviction, tolerates swings and rarely re-positions.":{"zh":"基于长期判断持有，能承受波动，不频繁改变仓位。","ko":"장기 확신으로 보유하고, 변동을 견디며, 포지션을 거의 바꾸지 않는다."},"About conviction in existing positions; mechanical periodic buying is closer to DCA Believer.":{"zh":"强调已有仓位的持有信念；定期机械买入更接近定投信徒。","ko":"기존 포지션에 대한 확신에 관한 것이며, 기계적 정기 매수는 DCA 신봉자에 가깝습니다."},"Long horizon":{"zh":"长期视角","ko":"장기 관점"},"Patient holder":{"zh":"持有耐心","ko":"인내하는 보유자"},"High conviction":{"zh":"高确信度","ko":"높은 확신"},"Risk Explorer":{"zh":"高风险探索者","ko":"리스크 탐험가"},"Actively trades high-volatility assets and prefers leverage or concentrated risk.":{"zh":"主动参与高波动标的，同时偏好高杠杆或集中风险。","ko":"고변동성 자산을 적극 매매하며, 레버리지나 집중 리스크를 선호한다."},"Holding memes alone isn't enough; there must be evidence of actively taking on high risk.":{"zh":"仅持有 meme 不足以判定；需同时有主动承担高风险的证据。","ko":"밈 보유만으로는 부족합니다. 고위험을 적극 감수한 증거가 있어야 합니다."},"Volatility seeker":{"zh":"高波动偏好","ko":"변동성 선호"},"Opportunity hunter":{"zh":"机会探索","ko":"기회 탐색"},"Fast iteration":{"zh":"快速试错","ko":"빠른 시도"},"Sniper":{"zh":"狙击手","ko":"스나이퍼"},"Waits at low frequency for clear conditions and acts only at planned levels.":{"zh":"低频等待明确条件，只在计划中的位置出手。","ko":"저빈도로 명확한 조건을 기다리고, 계획한 지점에서만 행동한다."},"About waiting and filtering; a self-described \"precise\" entry is not proof of timing skill.":{"zh":"强调等待与筛选，不能因为自述“精准”就认定择时能力强。","ko":"기다림과 선별에 관한 것이며, 스스로 말한 \"정밀한\" 진입이 타이밍 실력의 증거는 아닙니다."},"Patient entry":{"zh":"耐心入场","ko":"인내하는 진입"},"Clear conditions":{"zh":"条件明确","ko":"명확한 조건"},"Selective":{"zh":"选择性出手","ko":"선별적 진입"},"Swing Hunter":{"zh":"波段猎手","ko":"스윙 헌터"},"Holds for days to weeks, planning entries and exits around a trend or range.":{"zh":"持仓数天至数周，围绕一段趋势或区间制定进出场。","ko":"며칠에서 몇 주 보유하며, 추세나 레인지를 중심으로 진입과 청산을 계획한다."},"Distinct from minute-level intraday and multi-month holding.":{"zh":"区别于分钟级日内与数月以上持有。","ko":"분 단위 데이 트레이딩이나 수개월 보유와는 구별됩니다."},"Swing rhythm":{"zh":"波段节奏","ko":"스윙 리듬"},"Planned exits":{"zh":"计划离场","ko":"계획된 청산"},"Trend watcher":{"zh":"趋势观察","ko":"추세 관찰"},"Arb Researcher":{"zh":"套利研究者","ko":"아비트라지 연구자"},"Finds opportunity in spreads, funding and hedged structures.":{"zh":"围绕价差、资金费或对冲结构寻找机会。","ko":"스프레드, 펀딩, 헤지 구조에서 기회를 찾는다."},"Requires evidence of structural arbitrage; it never implies low risk or steady returns.":{"zh":"必须有结构性套利证据；不会据此承诺低风险或稳定收益。","ko":"구조적 아비트라지의 증거가 필요하며, 저위험이나 안정 수익을 의미하지 않습니다."},"Structure research":{"zh":"结构研究","ko":"구조 연구"},"Data-driven":{"zh":"数据驱动","ko":"데이터 기반"},"Hedge-minded":{"zh":"对冲意识","ko":"헤지 마인드"},"Grid Executor":{"zh":"网格执行者","ko":"그리드 실행자"},"Sets ranges and grids, managing buys and sells with repeatable rules.":{"zh":"设定价格区间与网格，用重复规则管理买卖。","ko":"레인지와 그리드를 설정하고, 반복 가능한 규칙으로 매매를 관리한다."},"Automation alone isn't a grid; there must be a range or grid strategy.":{"zh":"自动化工具本身不等于网格；必须有区间或网格策略。","ko":"자동화만으로는 그리드가 아닙니다. 레인지나 그리드 전략이 있어야 합니다."},"Rule-driven":{"zh":"规则驱动","ko":"규칙 기반"},"Range watcher":{"zh":"区间观察","ko":"레인지 관찰"},"repeat":{"zh":"重复执行","ko":"반복 실행"},"Narrative Trader":{"zh":"叙事交易者","ko":"내러티브 트레이더"},"Treats sector narratives, events and theme shifts as the main source of opportunity.":{"zh":"以赛道叙事、事件和主题变化作为主要机会来源。","ko":"섹터 내러티브, 이벤트, 테마 변화를 주요 기회 원천으로 삼는다."},"Reading the news isn't narrative trading; themes must actively drive decisions.":{"zh":"日常看新闻不等于叙事交易，需主动以主题推动决策。","ko":"뉴스를 읽는 것만으로는 내러티브 트레이딩이 아닙니다. 테마가 결정을 주도해야 합니다."},"Theme insight":{"zh":"主题洞察","ko":"테마 인사이트"},"Information-sensitive":{"zh":"信息敏感","ko":"정보 민감형"},"Narrative-driven":{"zh":"叙事驱动","ko":"내러티브 기반"},"Risk-First":{"zh":"风控优先者","ko":"리스크 퍼스트"},"Sets size, stops and drawdown limits before acting, and lets them govern decisions.":{"zh":"在行动前明确仓位、止损和回撤边界，并以此约束决策。","ko":"행동 전에 사이즈, 손절, 낙폭 한도를 정하고, 그것이 결정을 지배하게 한다."},"Not using leverage isn't automatically good risk control; this is about self-reported rule execution.":{"zh":"不开杠杆不自动等于优秀风控；强调自报的规则执行。","ko":"레버리지를 쓰지 않는 것이 곧 좋은 리스크 관리는 아닙니다. 자기 보고한 규칙 실행에 관한 것입니다."},"Risk first":{"zh":"风险优先","ko":"리스크 우선"},"position discipline":{"zh":"仓位纪律","ko":"포지션 규율"},"Clear boundaries":{"zh":"边界清晰","ko":"명확한 경계"},"Contrarian":{"zh":"逆向布局者","ko":"역발상 투자자"},"Scales in during declines or pessimism, accepting the uncertainty of being early.":{"zh":"在下跌或悲观阶段分批布局，接受较早入场的不确定性。","ko":"하락이나 비관 국면에 분할 진입하며, 이른 진입의 불확실성을 받아들인다."},"Distinct from entering after a breakout; averaging down is not a risk-managed contrarian strategy.":{"zh":"区别于突破后入场；不把补仓等同于有风控的逆向策略。","ko":"돌파 후 진입과 구별됩니다. 물타기는 리스크 관리된 역발상 전략이 아닙니다."},"Contrarian thinking":{"zh":"逆向思考","ko":"역발상 사고"},"Staged entries":{"zh":"分批布局","ko":"분할 진입"},"Cycle watcher":{"zh":"周期观察","ko":"사이클 관찰"},"Momentum Rider":{"zh":"动量跟随者","ko":"모멘텀 라이더"},"Follows the trend once strength or a breakout is confirmed.":{"zh":"在强势或突破得到确认后跟随趋势。","ko":"강세나 돌파가 확인되면 추세를 따른다."},"Describes an entry preference; \"chasing\" is never dressed up as skill or a returns rating.":{"zh":"描述入场偏好，不将“追高”包装为能力或收益评级。","ko":"진입 선호를 설명할 뿐, \"추격 매수\"를 실력이나 수익 평가로 포장하지 않습니다."},"Trend follower":{"zh":"趋势跟随","ko":"추세 추종"},"Breakout confirmation":{"zh":"突破确认","ko":"돌파 확인"},"Quick response":{"zh":"及时响应","ko":"빠른 대응"},"Day Trader":{"zh":"日内交易者","ko":"데이 트레이더"},"Holds from minutes to intraday, watching closely and executing fast.":{"zh":"分钟至日内持仓、频繁观察并快速执行。","ko":"분 단위에서 당일까지 보유하며, 밀착 관찰하고 빠르게 실행한다."},"Requires short cycles and high-frequency behaviour; using perps alone isn't enough.":{"zh":"需要短周期与高频行为配合，仅使用合约不够。","ko":"짧은 사이클과 고빈도 행동이 필요합니다. 선물 사용만으로는 부족합니다."},"Short cycles":{"zh":"短周期","ko":"단기 사이클"},"Hands-on":{"zh":"主动盯盘","ko":"직접 대응"},"Agile execution":{"zh":"执行敏捷","ko":"민첩한 실행"},"DCA Believer":{"zh":"定投信徒","ko":"DCA 신봉자"},"Accumulates on a fixed cadence, using a long horizon to avoid timing the market.":{"zh":"按固定节奏积累资产，以长周期视角减少择时。","ko":"정해진 리듬으로 축적하며, 장기 관점으로 마켓 타이밍을 피한다."},"Unlike Diamond Hands, the point is the method of continuous investing, not just holding.":{"zh":"区别于钻石手：重点是持续投入的方法，而不是只持有。","ko":"다이아몬드 핸즈와 달리, 핵심은 단순 보유가 아닌 지속 투자의 방법입니다."},"Fixed cadence":{"zh":"定期积累","ko":"정기 매수"},"Low-frequency decisions":{"zh":"低频决策","ko":"저빈도 결정"},"Which market do you follow most?":{"zh":"你最常关注什么市场？","ko":"가장 자주 보는 시장은?"},"Pick your home ground, not a market you glanced at once.":{"zh":"选择你的主场，而不是偶尔看过的市场。","ko":"한 번 스친 시장이 아닌, 당신의 홈그라운드를 고르세요."},"Majors and perps":{"zh":"主流资产与合约","ko":"메이저 자산과 선물"},"New on-chain assets / memes":{"zh":"链上新资产 / Meme","ko":"온체인 신규 자산 / 밈"},"Finding early opportunities":{"zh":"发现早期机会","ko":"초기 기회 발견"},"Long-term spot":{"zh":"长期现货","ko":"장기 현물"},"Accumulate and allocate":{"zh":"积累与配置","ko":"축적과 배분"},"Spreads / funding":{"zh":"价差 / 资金费","ko":"스프레드 / 펀딩"},"Arbitrage and hedging research":{"zh":"研究套利与对冲","ko":"아비트라지와 헤지 연구"},"Still observing and learning":{"zh":"仍在观察与学习","ko":"아직 관찰하고 배우는 중"},"No fixed market yet":{"zh":"暂时没有固定市场","ko":"아직 정해진 시장 없음"},"How do you usually pace your positions?":{"zh":"你通常怎样安排持仓节奏？","ko":"포지션의 리듬은 보통 어떤가요?"},"Answer for your most common behaviour.":{"zh":"按最常见的行为作答。","ko":"가장 흔한 행동 기준으로 답하세요."},"Minutes to intraday, many round trips":{"zh":"分钟至日内，多次进出","ko":"분 단위에서 당일까지, 잦은 매매"},"Days to weeks":{"zh":"几天至几周","ko":"며칠에서 몇 주"},"Months or longer":{"zh":"几个月以上","ko":"몇 달 이상"},"Low frequency; act only when conditions are met":{"zh":"低频等待，条件到了才做","ko":"저빈도; 조건이 충족될 때만 행동"},"No stable habit yet":{"zh":"还没有稳定习惯","ko":"아직 안정된 습관 없음"},"What usually makes you act?":{"zh":"什么通常促使你行动？","ko":"보통 무엇이 행동을 촉발하나요?"},"Choose the closest one.":{"zh":"选择最接近你的一项。","ko":"가장 가까운 항목을 선택하세요."},"My long-term view hasn't changed, so I keep holding":{"zh":"长期判断没有改变，继续持有","ko":"장기 관점이 바뀌지 않았으니 계속 보유한다"},"A fixed schedule; I invest periodically":{"zh":"固定时间，定期投入","ko":"정해진 일정; 정기적으로 투자한다"},"A price breakout; I follow strength":{"zh":"价格突破，跟随强势","ko":"가격 돌파; 강세를 따른다"},"Drawdowns or panic; I scale in":{"zh":"下跌或恐慌时分批布局","ko":"하락이나 패닉 때 분할 매수한다"},"A new narrative, event or theme":{"zh":"新叙事、事件或主题变化","ko":"새로운 내러티브, 이벤트, 테마"},"Repeated execution on a range grid":{"zh":"按区间网格重复执行","ko":"레인지 그리드에서 반복 실행"},"A spread or funding opportunity appears":{"zh":"出现价差或资金费机会","ko":"스프레드나 펀딩 기회가 나타날 때"},"Every preset condition is met":{"zh":"预设条件全部满足","ko":"모든 사전 조건이 충족됨"},"Still trying things; no fixed way":{"zh":"仍在尝试，没有固定方式","ko":"아직 시도 중; 정해진 방식 없음"},"How do you handle risk?":{"zh":"你怎么处理风险？","ko":"리스크를 어떻게 다루나요?"},"This is a behavioural preference, not a risk-capacity test.":{"zh":"这是行为偏好，不是风险能力测验。","ko":"행동 성향에 관한 것이며, 리스크 감내력 테스트가 아닙니다."},"Risk budget, size and exits first":{"zh":"先定风险预算、仓位和退出条件","ko":"리스크 예산, 사이즈, 청산을 먼저"},"I set stops and exit on plan":{"zh":"有止损，会按计划退出","ko":"손절을 정하고 계획대로 청산한다"},"I accept high leverage or concentration on purpose":{"zh":"主动接受高杠杆或集中风险","ko":"의도적으로 높은 레버리지나 집중을 감수한다"},"I adjust in the moment":{"zh":"根据当时判断临时调整","ko":"그때그때 판단해 조정한다"},"No rules yet":{"zh":"尚未形成规则","ko":"아직 규칙 없음"},"How do you execute your ideas?":{"zh":"你如何执行自己的想法？","ko":"아이디어를 어떻게 실행하나요?"},"Tooling never decides your identity or any membership tier.":{"zh":"工具使用不会自动决定身份或会员等级。","ko":"도구 사용이 신분이나 멤버십 등급을 결정하지 않습니다."},"I watch the tape and place orders myself":{"zh":"亲自盯盘和下单","ko":"직접 시세를 보고 주문한다"},"Write the plan, execute on trigger":{"zh":"先写计划，触发后执行","ko":"계획을 쓰고, 트리거에 실행"},"Scripts or automation run the rules":{"zh":"用脚本或自动化运行规则","ko":"스크립트나 자동화가 규칙을 실행"},"Periodic check-ins; otherwise hands off":{"zh":"定期检查，平时尽量不动","ko":"주기적 점검; 그 외엔 손대지 않음"},"Mostly research; I rarely execute":{"zh":"目前主要研究，不常执行","ko":"주로 리서치; 실행은 드물다"},"What do you mostly base your judgement on?":{"zh":"你主要依据什么形成判断？","ko":"판단의 주된 근거는 무엇인가요?"},"Used to explain your style; we never read private content.":{"zh":"用于解释风格，不会读取你的私密内容。","ko":"스타일 설명에만 사용; 비공개 콘텐츠는 읽지 않습니다."},"Charts, price and volume":{"zh":"图表、价格与成交量","ko":"차트, 가격, 거래량"},"On-chain data and flows":{"zh":"链上数据与资金流","ko":"온체인 데이터와 자금 흐름"},"Macro, cycles and liquidity":{"zh":"宏观、周期与流动性","ko":"매크로, 사이클, 유동성"},"News, themes and community discussion":{"zh":"新闻、主题和社区讨论","ko":"뉴스, 테마, 커뮤니티 논의"},"Several sources, cross-checked":{"zh":"多种来源交叉验证","ko":"여러 출처를 교차 검증"},"No fixed source yet":{"zh":"还没有固定信息来源","ko":"아직 정해진 출처 없음"},"Your description mentions: ":{"zh":"自述提到：","ko":"자기소개에서 언급: "},"The material so far doesn't form a clear trading style. Add concrete behaviour and generate again.":{"zh":"目前的材料尚未形成清晰的交易风格。补充具体行为后可重新生成。","ko":"지금까지의 내용으로는 명확한 스타일이 형성되지 않습니다. 구체적인 행동을 추가해 다시 생성하세요."},"Exploring":{"zh":"探索中","ko":"탐색 중"},"Profile in progress":{"zh":"画像待完善","ko":"프로필 작성 중"},"Timing focus":{"zh":"择时关注","ko":"타이밍 중심"},"On-chain participation":{"zh":"链上参与","ko":"온체인 참여"},"Macro focus":{"zh":"宏观关注","ko":"매크로 중심"},"Risk planning":{"zh":"风险规划","ko":"리스크 계획"},"Rule execution":{"zh":"规则执行","ko":"규칙 실행"},"Make time your home ground.":{"zh":"把时间，变成你的主场。","ko":"시간을 당신의 홈그라운드로."},"The market shouts; you hold your own rhythm.":{"zh":"市场喧嚣，你有自己的持有节奏。","ko":"시장은 소리치지만, 당신은 자신의 리듬을 지킨다."},"Beyond the edge, your coordinates.":{"zh":"边界之外，也有你的坐标。","ko":"경계 너머, 당신의 좌표."},"Curiosity leads the way; risk is yours to weigh.":{"zh":"好奇心带你向前，风险由你认真衡量。","ko":"호기심이 길을 열고, 리스크는 당신이 저울질한다."},"Patience is your entry.":{"zh":"耐心，是你的入场方式。","ko":"인내가 당신의 진입 방식."},"Chase nothing; wait for your moment.":{"zh":"不追逐每一次波动，只等待自己的时刻。","ko":"쫓지 않고, 당신의 순간을 기다린다."},"Every leg of the market has your rhythm.":{"zh":"每一段行情，都有你的节奏。","ko":"시장의 모든 구간에 당신의 리듬이 있다."},"Find room between trends; act within plan.":{"zh":"在趋势之间寻找空间，在计划之内行动。","ko":"추세 사이의 여지를 찾고, 계획 안에서 움직인다."},"See the other possibility between prices.":{"zh":"看见价格之间的另一种可能。","ko":"가격 사이의 또 다른 가능성을 본다."},"Your edge hides in structure, spreads and detail.":{"zh":"你的视角，藏在结构、价差与细节里。","ko":"당신의 엣지는 구조, 스프레드, 디테일에 숨어 있다."},"Write the market's swings into rules.":{"zh":"把市场的起伏，写进规则。","ko":"시장의 등락을 규칙으로 쓴다."},"Give every execution its own order.":{"zh":"让每一次执行，都有自己的秩序。","ko":"모든 실행에 고유한 질서를."},"Read the story, write your call.":{"zh":"读懂故事，也写下你的判断。","ko":"이야기를 읽고, 판단을 쓴다."},"Your eyes follow the narrative of the era.":{"zh":"你的目光，跟随正在发生的时代叙事。","ko":"당신의 시선은 시대의 내러티브를 따른다."},"Confidence comes from clear boundaries.":{"zh":"你的底气，来自清晰的边界。","ko":"자신감은 명확한 경계에서 온다."},"Define risk first, then move.":{"zh":"先定义风险，再决定向前。","ko":"리스크를 먼저 정의하고, 움직인다."},"When the crowd turns, you keep watching.":{"zh":"人群转身时，你仍在观察。","ko":"군중이 돌아설 때, 당신은 계속 지켜본다."},"On the cycle's far side, set your own pace.":{"zh":"在周期的另一面，寻找自己的布局节奏。","ko":"사이클의 반대편에서, 당신의 속도를 정한다."},"Trends appear; you have your answer.":{"zh":"趋势出现，你有自己的回应。","ko":"추세가 나타나면, 당신의 답이 있다."},"Watch strength, wait for confirmation, act on plan.":{"zh":"观察强势，等待确认，然后按计划行动。","ko":"강세를 보고, 확인을 기다리고, 계획대로 움직인다."},"Your home ground is the present.":{"zh":"你的主场，在每一个当下。","ko":"당신의 홈그라운드는 지금 이 순간."},"Short cycles, your own execution rhythm.":{"zh":"专注短周期，跟随自己的执行节奏。","ko":"짧은 사이클, 당신만의 실행 리듬."},"Give every persistence to time.":{"zh":"把每一次坚持，交给时间。","ko":"모든 꾸준함을 시간에 맡긴다."},"Accumulate at your pace; make long-term a habit.":{"zh":"按自己的节奏积累，让长期成为习惯。","ko":"당신의 속도로 축적하고, 장기를 습관으로."},"Your style is still unfolding.":{"zh":"你的风格，还在展开。","ko":"당신의 스타일은 아직 펼쳐지는 중."},"No rush to be defined; your next choices will sharpen the outline.":{"zh":"不急着被定义，下一次选择会让轮廓更清晰。","ko":"서둘러 정의될 필요는 없습니다. 다음 선택이 윤곽을 선명하게 합니다."},"Card portrait":{"zh":"卡片头像","ko":"카드 프로필 사진"},"Six-axis self-reported style radar, not a skill score":{"zh":"六维自报风格图，非能力评分","ko":"6축 자기 보고 스타일 레이더, 실력 점수가 아님"},"Not enough data":{"zh":"信息不足","ko":"정보 부족"},"High":{"zh":"较高","ko":"높음"},"Medium":{"zh":"中等","ko":"중간"},"Low":{"zh":"较低","ko":"낮음"},"Style still forming":{"zh":"风格探索中","ko":"스타일 형성 중"},"More real habits and experience make this card more like you.":{"zh":"更多真实的习惯与经历，会让这张卡更像你。","ko":"진짜 습관과 경험이 많을수록 카드는 더 당신답게 됩니다."},"Profile source":{"zh":"画像来源","ko":"프로필 출처"},"Survey + self-report":{"zh":"问卷 + 自述","ko":"설문 + 자기소개"},"Status":{"zh":"身份状态","ko":"신분 상태"},"Provisional style":{"zh":"暂定风格","ko":"임시 스타일"},"Self-reported style":{"zh":"自报风格","ko":"자기 보고 스타일"},"Style profile ≠ trading skill · not a returns or membership rating":{"zh":"风格画像 ≠ 交易能力 · 不代表收益或会员等级","ko":"스타일 프로필 ≠ 트레이딩 실력 · 수익이나 멤버십 평가가 아님"},"Connected":{"zh":"已连接","ko":"연결됨"},"Preview account":{"zh":"预览账号","ko":"미리보기 계정"},"Public identity":{"zh":"公开身份","ko":"공개 신분"},"Your style deserves a card of its own.":{"zh":"你的风格，值得一张专属卡。","ko":"당신의 스타일엔 전용 카드가 어울린다."},"Twitter not linked · standalone card":{"zh":"Twitter 未公开 · 独立身份卡","ko":"Twitter 미연결 · 독립 카드"},"Card preview QR":{"zh":"卡片预览二维码","ko":"카드 미리보기 QR"},"Please enter a wallet address.":{"zh":"请填写钱包地址。","ko":"지갑 주소를 입력해 주세요."},"I mostly follow BTC and ETH, hold for the long term and review my thesis quarterly. I set a risk budget and size before acting and rarely change plans on short-term emotion. I like turning macro shifts into short notes for the community.":{"zh":"我主要关注 BTC 和 ETH，习惯长期持有，按季度检查自己的判断。行动前先定风险预算和仓位，很少因为短期情绪改变计划。喜欢把宏观变化写成简短笔记分享给社区。","ko":"주로 BTC와 ETH를 보며 장기 보유하고, 분기마다 내 논지를 점검합니다. 행동 전에 리스크 예산과 사이즈를 정하고, 단기 감정으로 계획을 바꾸는 일은 거의 없습니다. 매크로 변화를 커뮤니티용 짧은 노트로 정리하는 것을 좋아합니다."},"Sample filled in; edit any time":{"zh":"已填入示例，可随时修改","ko":"샘플이 입력됨; 언제든 수정 가능"},"Sample data filled in":{"zh":"已填入测试资料，可直接生成身份卡","ko":"샘플 데이터가 입력되었습니다"},"Please answer every question.":{"zh":"请完成全部问卷选项。","ko":"모든 질문에 답해 주세요."},"Please write a few words about how you trade.":{"zh":"请写几句你的交易方式。","ko":"트레이딩 방식을 몇 마디 적어 주세요."},"Please enter a card nickname.":{"zh":"请填写卡片昵称。","ko":"카드 닉네임을 입력해 주세요."},"Please enter a valid D0 sign-in email.":{"zh":"请填写有效的 D0 登录邮箱。","ko":"유효한 D0 로그인 이메일을 입력해 주세요."},"Please enter a valid wallet address.":{"zh":"请填写一个有效的钱包地址。","ko":"유효한 지갑 주소를 입력해 주세요."},"Please choose a PNG, JPG or WebP under 4 MB.":{"zh":"请选择不超过 4 MB 的 PNG、JPG 或 WebP 图片。","ko":"4 MB 이하의 PNG, JPG 또는 WebP를 선택해 주세요."},"Downloaded this side as PNG":{"zh":"已下载当前卡面 PNG","ko":"이 면을 PNG로 다운로드했습니다"},"Image export failed, please try again.":{"zh":"图片生成失败，请重试。","ko":"이미지 생성에 실패했습니다. 다시 시도해 주세요."},"Copied":{"zh":"已复制","ko":"복사됨"},"Your browser blocked copying; select the text and copy it manually.":{"zh":"浏览器不允许自动复制，请选中文本手动复制。","ko":"브라우저가 복사를 차단했습니다. 텍스트를 선택해 직접 복사해 주세요."},"Back to home":{"zh":"返回首页","ko":"홈으로"},"The market has a thousand voices.":{"zh":"市场有无数种声音。","ko":"시장에는 천 개의 목소리가 있다."},"Make yours":{"zh":"让人记住","ko":"당신의 목소리를"},"the one they remember.":{"zh":"你的那一种。","ko":"기억에 남는 목소리로."},"Create my card ":{"zh":"生成我的身份卡 ","ko":"내 카드 만들기 "},"About 3 minutes":{"zh":"约 3 分钟","ko":"약 3분"}," 12 style archetypes":{"zh":" 12 种风格原型","ko":" 12가지 스타일 원형"}," Self-reported, not a performance rating":{"zh":" 自述画像，非收益评级","ko":" 자기 보고 프로필, 성과 평가가 아님"},"01 Survey":{"zh":"01 回答问卷","ko":"01 설문"},"02 Describe yourself":{"zh":"02 介绍自己","ko":"02 자기소개"},"03 Complete identity":{"zh":"03 完善身份","ko":"03 신분 완성"},"04 Get your card":{"zh":"04 生成卡片","ko":"04 카드 받기"},"Every choice":{"zh":"每一个选择，","ko":"모든 선택이"},"brings it closer to you.":{"zh":"都更接近你。","ko":"당신에게 더 가까워집니다."},"Trading habits":{"zh":"交易习惯","ko":"트레이딩 습관"},"About you":{"zh":"自我描述","ko":"자기소개"},"Identity & contact":{"zh":"身份与联系方式","ko":"신분 및 연락처"},"Your card":{"zh":"专属身份卡","ko":"나의 카드"},"Your raw answers never appear on the card.":{"zh":"你的原始回答不会出现在卡片上。","ko":"원본 답변은 카드에 표시되지 않습니다."},"You can go back and edit before generating.":{"zh":"生成前可以返回修改。","ko":"생성 전에 돌아가 수정할 수 있습니다."},"Demo only: fills the form with sample data, no Twitter connection":{"zh":"仅供 Demo 测试，填写当前表单资料，不连接 Twitter","ko":"데모 전용: 샘플 데이터로 폼을 채우며, Twitter 연결은 없음"},"Autofill (test)":{"zh":"一键填写（测试）","ko":"자동 입력 (테스트)"},"First, your trading habits.":{"zh":"先聊聊你的交易习惯。","ko":"먼저, 트레이딩 습관부터."},"No right answers. Pick what you actually do.":{"zh":"没有“正确答案”。按平时真实的选择来回答。","ko":"정답은 없습니다. 실제로 하는 대로 고르세요."}," / 6 answered":{"zh":" / 6 已完成","ko":" / 6 완료"},"Continue ":{"zh":"继续 ","ko":"계속 "},"Tell us what the options miss.":{"zh":"说说选项以外的你。","ko":"선택지에 없는 당신의 이야기를 들려주세요."},"What are you good at, what do you stick to, and where do you hesitate?":{"zh":"你擅长什么、坚持什么，又在哪些地方容易犹豫？","ko":"무엇을 잘하고, 무엇을 지키며, 어디에서 망설이나요?"},"My market":{"zh":"我的主场","ko":"나의 시장"},"My habits":{"zh":"我的习惯","ko":"나의 습관"},"My rules":{"zh":"我的原则","ko":"나의 원칙"},"My weak spot":{"zh":"我的短板","ko":"나의 약점"},"For example: I mostly follow BTC and ETH and like to scale in when the market panics. I hold for a few weeks and set size and exits before entering. I turn research into notes for the community…":{"zh":"例如：我主要关注 BTC 和 ETH，喜欢在市场恐慌时分批布局。一般持有几周，进场前会设好仓位和退出条件。习惯把研究整理成笔记分享给社区……","ko":"예: 주로 BTC와 ETH를 보고, 시장이 패닉일 때 분할 매수하는 편입니다. 몇 주 보유하며, 진입 전에 사이즈와 청산을 정합니다. 리서치를 커뮤니티용 노트로 정리합니다…"},"20–800 characters. Share only what you want used for your profile.":{"zh":"20–800 字。只分享你愿意用于画像的信息。","ko":"20–800자. 프로필에 쓰길 원하는 내용만 공유하세요."},"Real habits beat \"I'm a great trader\".":{"zh":"描述真实习惯，比一句“我是高手”更有用。","ko":"진짜 습관이 \"나는 고수다\"보다 낫습니다."},"The survey gives structure; your description adds context. We never use it to estimate returns, win rate or follower influence.":{"zh":"问卷提供结构，自述补充语境。我们不会用这段文字推算收益、胜率或粉丝影响力。","ko":"설문은 구조를, 자기소개는 맥락을 더합니다. 수익률, 승률, 팔로워 영향력 추정에는 절대 사용하지 않습니다."}," Back":{"zh":" 上一步","ko":" 뒤로"},"Make this card truly yours.":{"zh":"让这张卡，真正属于你。","ko":"이 카드를 진짜 당신의 것으로."},"Connect Twitter, or generate without it.":{"zh":"连接 Twitter，或不连接直接生成。","ko":"Twitter를 연결하거나, 연결 없이 생성하세요."},"Card nickname ":{"zh":"卡片昵称 ","ko":"카드 닉네임 "},"Required":{"zh":"必填","ko":"필수"},"What should people call you?":{"zh":"你希望大家如何称呼你","ko":"사람들이 당신을 어떻게 부르면 좋을까요?"},"Up to 24 characters; long names wrap.":{"zh":"最多 24 个字符，长名称自动换行。","ko":"최대 24자; 긴 이름은 줄바꿈됩니다."},"Connect your Twitter":{"zh":"连接你的 Twitter","ko":"Twitter 연결하기"},"Twitter connected":{"zh":"Twitter 已连接","ko":"Twitter 연결됨"},"Public profile only. No posts, no follows.":{"zh":"只读取公开资料，不发布推文，不自动关注。","ko":"공개 프로필만 사용. 게시나 팔로우 없음."},"Manage connection":{"zh":"管理连接","ko":"연결 관리"},"Your D0 sign-in email (or the one you'll sign up with).":{"zh":"请填写你登录 D0 时使用的邮箱；如果是新用户，请填写你准备用来登录 D0 的邮箱","ko":"D0 로그인 이메일 (또는 가입에 쓸 이메일)."},"Optional":{"zh":"选填","ko":"선택"},"Your Discord username":{"zh":"你的 Discord 用户名","ko":"Discord 사용자명"},"Wallet address ":{"zh":"钱包地址 ","ko":"지갑 주소 "},"One or the other, a single address":{"zh":"二选一，仅填写一个地址","ko":"둘 중 하나, 주소 하나만"},"Address type":{"zh":"地址类型","ko":"주소 유형"},"Your EVM address, starting with 0x":{"zh":"填写你的 0x 开头的 EVM 地址","ko":"0x로 시작하는 EVM 주소"},"Your Solana wallet address":{"zh":"填写你的 Solana 钱包地址","ko":"Solana 지갑 주소"},"Your everyday wallet.":{"zh":"填写你常用的钱包地址。","ko":"평소 사용하는 지갑 주소."},"Portrait preview":{"zh":"头像预览","ko":"프로필 미리보기"},"Your own image, or keep the generated pattern.":{"zh":"使用你自己的图片，或保留生成的身份图案。","ko":"직접 이미지를 쓰거나, 생성된 패턴을 유지하세요."}," Upload portrait":{"zh":" 上传头像","ko":" 프로필 사진 업로드"},"Remove":{"zh":"移除","ko":"제거"},"Reading your style…":{"zh":"正在整理你的风格…","ko":"스타일을 읽는 중…"},"Generate card":{"zh":"生成身份卡","ko":"카드 생성"},"Card preview · your style is generated when you finish":{"zh":"卡面预览 · 完成后生成你的专属风格","ko":"카드 미리보기 · 완료하면 스타일이 생성됩니다"}," Start over":{"zh":" 重新开始","ko":" 다시 시작"},", your trading identity is":{"zh":"，你的交易身份是","ko":", 당신의 트레이딩 신분은"},"First impression · provisional":{"zh":"风格初印象 · 暂定","ko":"첫인상 · 임시"}," Share":{"zh":" 分享","ko":" 공유"},"Rendering image…":{"zh":"生成图片…","ko":"이미지 생성 중…"},"Save card":{"zh":"保存身份卡","ko":"카드 저장"},"Show friends your tribe.":{"zh":"让朋友看看，你是哪一派。","ko":"친구들에게 당신의 부족을 보여주세요."},"Identity":{"zh":"身份正面","ko":"신분 카드"},"Style ":{"zh":"风格背面 ","ko":"스타일 "},"Twelve trading styles":{"zh":"十二种交易风格","ko":"12가지 트레이딩 스타일"},"Twelve styles. One has your name on it.":{"zh":"十二种风格，你有自己的名字。","ko":"12가지 스타일. 그중 하나에 당신의 이름이."},"The style is yours. So is the call.":{"zh":"风格是你的，决定也是。","ko":"스타일도, 결정도 당신의 것."},"Connect Twitter":{"zh":"连接 Twitter","ko":"Twitter 연결"},"Share card":{"zh":"分享身份卡","ko":"카드 공유"},"Close":{"zh":"关闭弹窗","ko":"닫기"},"Confirm this identity":{"zh":"确认连接这个身份","ko":"이 계정으로 연결"},"Attach your public Twitter identity so people can find you.":{"zh":"关联你的 Twitter 公开身份，让大家更容易找到你。","ko":"공개 Twitter 신분을 연결해 사람들이 당신을 찾게 하세요."},"Twitter username":{"zh":"Twitter 用户名","ko":"Twitter 사용자명"},"1–15 letters, numbers or underscores.":{"zh":"1–15 位字母、数字或下划线。","ko":"영문, 숫자, 밑줄 1–15자."},"Disconnect":{"zh":"断开连接","ko":"연결 해제"},"Allow Donut Identity to use your public name, username and avatar.":{"zh":"允许 Donut Identity 使用公开昵称、用户名及头像。","ko":"Donut Identity가 공개 이름, 사용자명, 아바타를 사용하도록 허용합니다."}," Never posts, never reads DMs":{"zh":" 不发布推文，不读取私信","ko":" 게시하지 않고, DM을 읽지 않습니다"},"Agree and connect ":{"zh":"同意并连接 ","ko":"동의하고 연결 "},"Cancel authorisation":{"zh":"取消授权","ko":"인증 취소"},"Share only the card you've confirmed.":{"zh":"只分享你确认的卡面。","ko":"확인한 카드만 공유하세요."},"The link shows the card only, never your answers or contact details.":{"zh":"链接仅展示卡面，不包含你的回答或联系方式。","ko":"링크는 카드만 보여주며, 답변이나 연락처는 포함하지 않습니다."}," Show Twitter username on the shared card":{"zh":" 分享卡面显示 Twitter 用户名","ko":" 공유 카드에 Twitter 사용자명 표시"},"Card preview link":{"zh":"卡片预览链接","ko":"카드 미리보기 링크"}," Copy link":{"zh":" 复制卡片预览链接","ko":" 링크 복사"},"Copy share text":{"zh":"复制分享文案","ko":"공유 문구 복사"},"Test your Trading Personality on Donut D0":{"zh":"在 Donut D0 测测你的交易人格","ko":"Donut D0에서 트레이딩 성향을 테스트하세요"},"presented by Donut.ai":{"zh":"由 Donut.ai 呈现","ko":"presented by Donut.ai"},"LOCKED":{"zh":"未解锁","ko":"잠김"},"Language":{"zh":"语言","ko":"언어"},"Answer a few questions. D0 turns them into your card.":{"zh":"回答几个问题，D0 把它变成你的身份卡。","ko":"몇 가지 질문에 답하면, D0가 당신의 카드로 만들어 드립니다."},"Tap the card to flip":{"zh":"点击卡片翻面","ko":"카드를 탭하면 뒤집힙니다"}};
  var q = new URLSearchParams(location.search);
  var stored = null; try { stored = localStorage.getItem("donut-identity-lang"); } catch (e) {}
  var lang = q.get("lang") || stored || "en";   // English by default; the switcher (or ?lang=) changes it
  if (!/^(en|zh|ko)$/.test(lang)) lang = "en";
  if (q.get("lang")) { try { localStorage.setItem("donut-identity-lang", lang); } catch (e) {} }
  document.documentElement.lang = { en: "en", zh: "zh-CN", ko: "ko" }[lang];
  document.documentElement.setAttribute("data-lang", lang);
  var R = {}; Object.keys(D).forEach(function (k) { R[D[k].zh] = k; R[D[k].ko] = k; });
  function t(s) { var e = D[s]; return (e && e[lang]) || s; }
  window.__t = t;
  window.DONUT_I18N = {
    lang: lang, t: t, langs: [["en", "EN"], ["zh", "中文"], ["ko", "한국어"]],
    en: function (s) { s = String(s || "").trim(); return R[s] || R[s.replace(/[.。]$/, "")] || s; },   // translated label → English key
    set: function (l) { try { localStorage.setItem("donut-identity-lang", l); } catch (e) {} var u = new URL(location.href); u.searchParams.set("lang", l); u.searchParams.set("intro", "0"); location.replace(u.href); }
  };
})();
